%% Comparar MPC open-loop en OpenFAST
% Compara:
%   1) Base original turbulento
%   2) Open-loop BASE, pitch base leído desde archivo
%   3) Open-loop MPC, pitch base + corrección MPC
%
% Importante:
% Esto NO es MPC cerrado en OpenFAST.
% Es una evaluación no lineal en OpenFAST con señales MPC precomputadas.

clear; clc; close all;

rootDir = fullfile(getenv('USERPROFILE'), 'Desktop', 'TFM_OpenFast');
toolboxDir = fullfile(rootDir, 'Matlab', 'Matlab_Toolbox');
resRoot = fullfile(rootDir, 'Resultados');

addpath(genpath(toolboxDir));

outDir = fullfile(resRoot, 'Comparativa_MPC_OpenLoop');

if ~exist(outDir, 'dir')
    mkdir(outDir);
end

%% Configuración

tTrans = 500;              % tiempo descartado como transitorio [s]
mDEL = 10;                 % exponente fatiga
Neq = 1e6;                 % ciclos equivalentes
betaRateMax_deg_s = 2.0;   % límite usado para NAT [%]

%% Casos a comparar

cases = struct([]);

cases(1).name = "Base";
cases(1).label = "Base original";
cases(1).folder = fullfile(resRoot, 'CasoB_v16_turbulento');

cases(2).name = "OL_BASE";
cases(2).label = "Open-loop base";
cases(2).folder = fullfile(resRoot, 'MPC_OL_BASE_CasoB_v16_turbulento');

cases(3).name = "OL_MPC";
cases(3).label = "Open-loop MPC";
cases(3).folder = fullfile(resRoot, 'MPC_OL_MPC_CasoB_v16_turbulento_FIX');
%% Leer y procesar

rows = {};
signals = struct([]);

for k = 1:numel(cases) %[output:group:5de9fe1c]

    fprintf("\nProcesando: %s\n", cases(k).label); %[output:525765a5] %[output:176d5ae6] %[output:5a09166b]

    outbFile = findOutb(cases(k).folder);

    if outbFile == ""
        warning("No encuentro .outb para %s en:\n%s", ...
            cases(k).label, cases(k).folder);
        continue;
    end

    fprintf("Archivo encontrado:\n%s\n", outbFile); %[output:87e87101] %[output:8cda427d] %[output:615142c3]

    [X, ChanName, ChanUnit] = ReadFASTbinary(char(outbFile)); %[output:10201c15] %[output:4e039b1f] %[output:19e31c70]

    names = cleanNames(ChanName);
    units = cleanNames(ChanUnit);

    S = buildSignals(X, names, units);

    idx = S.Time >= tTrans;

    t = S.Time(idx);

    %% DEL raíz de pala

    DEL1 = calcDEL(S.RootMyb1(idx), mDEL, Neq);
    DEL2 = calcDEL(S.RootMyb2(idx), mDEL, Neq);
    DEL3 = calcDEL(S.RootMyb3(idx), mDEL, Neq);

    DEL_mean_kNm = mean([DEL1 DEL2 DEL3], 'omitnan');
    DEL_mean_MNm = DEL_mean_kNm / 1000;

    %% NAT pitch total

    NAT1 = calcNAT(t, S.BldPitch1(idx), betaRateMax_deg_s);
    NAT2 = calcNAT(t, S.BldPitch2(idx), betaRateMax_deg_s);
    NAT3 = calcNAT(t, S.BldPitch3(idx), betaRateMax_deg_s);

    NAT_total_mean_pct = mean([NAT1 NAT2 NAT3], 'omitnan');

    %% Pitch IPC real: quitar componente colectiva

    betaMat = [S.BldPitch1(idx), S.BldPitch2(idx), S.BldPitch3(idx)];
    betaCol = mean(betaMat, 2, 'omitnan');
    betaIPC = betaMat - betaCol;

    RMS_IPC_1 = rms(betaIPC(:,1), 'omitnan');
    RMS_IPC_2 = rms(betaIPC(:,2), 'omitnan');
    RMS_IPC_3 = rms(betaIPC(:,3), 'omitnan');

    RMS_IPC_mean_deg = mean([RMS_IPC_1 RMS_IPC_2 RMS_IPC_3], 'omitnan');
    Max_IPC_deg = max(abs(betaIPC), [], 'all', 'omitnan');

    betaDotIPC = zeros(size(betaIPC));

    for j = 1:3
        betaDotIPC(2:end,j) = diff(betaIPC(:,j)) ./ diff(t);
    end

    NAT_IPC_mean_pct = 100 * mean(abs(betaDotIPC), 'all', 'omitnan') / betaRateMax_deg_s;

    %% Otras métricas

    STD_GenPwr_MW = std(S.GenPwr_MW(idx), 'omitnan');
    STD_RotSpeed_rpm = std(S.RotSpeed(idx), 'omitnan');

    RMS_PtfmPitch_deg = rmsDemean(S.PtfmPitch(idx));
    RMS_PtfmSurge_m   = rmsDemean(S.PtfmSurge(idx));

    RMS_Mtilt_MNm = rmsDemean(S.Mtilt(idx)) / 1000;
    RMS_Myaw_MNm  = rmsDemean(S.Myaw(idx)) / 1000;

    Mean_GenPwr_MW = mean(S.GenPwr_MW(idx), 'omitnan');
    Mean_RotSpeed_rpm = mean(S.RotSpeed(idx), 'omitnan');
    Mean_BldPitch_deg = mean(betaCol, 'omitnan');

    %% Guardar fila

    rows(end+1,:) = {
        char(cases(k).label), ...
        DEL_mean_MNm, ...
        NAT_total_mean_pct, ...
        RMS_IPC_mean_deg, ...
        Max_IPC_deg, ...
        NAT_IPC_mean_pct, ...
        STD_GenPwr_MW, ...
        STD_RotSpeed_rpm, ...
        RMS_PtfmPitch_deg, ...
        RMS_PtfmSurge_m, ...
        RMS_Mtilt_MNm, ...
        RMS_Myaw_MNm, ...
        Mean_GenPwr_MW, ...
        Mean_RotSpeed_rpm, ...
        Mean_BldPitch_deg
    };

    %% Guardar señales para gráficas

    signals(k).name = cases(k).name;
    signals(k).label = cases(k).label;
    signals(k).S = S;
    signals(k).idx = idx;
    signals(k).t = S.Time;
    signals(k).betaIPC = nan(size(S.Time,1),3);
    signals(k).betaIPC(idx,:) = betaIPC;

end %[output:group:5de9fe1c]

%% Crear tabla

tablaMPC_OpenFAST = cell2table(rows, ...
    'VariableNames', { ...
    'Caso', ...
    'DEL_RootMyb_mean_MNm', ...
    'NAT_pitch_total_pct', ...
    'RMS_IPC_mean_deg', ...
    'Max_IPC_deg', ...
    'NAT_IPC_mean_pct', ...
    'STD_GenPwr_MW', ...
    'STD_RotSpeed_rpm', ...
    'RMS_PtfmPitch_deg', ...
    'RMS_PtfmSurge_m', ...
    'RMS_Mtilt_MNm', ...
    'RMS_Myaw_MNm', ...
    'Mean_GenPwr_MW', ...
    'Mean_RotSpeed_rpm', ...
    'Mean_BldPitch_deg'});

%% Variaciones respecto a Base original

idxBase = strcmp(tablaMPC_OpenFAST.Caso, 'Base original');

if any(idxBase)

    DEL_base = tablaMPC_OpenFAST.DEL_RootMyb_mean_MNm(idxBase);
    NAT_base = tablaMPC_OpenFAST.NAT_pitch_total_pct(idxBase);
    PtfmPitch_base = tablaMPC_OpenFAST.RMS_PtfmPitch_deg(idxBase);
    PtfmSurge_base = tablaMPC_OpenFAST.RMS_PtfmSurge_m(idxBase);

    tablaMPC_OpenFAST.Delta_DEL_vs_Base_pct = ...
        100 * (tablaMPC_OpenFAST.DEL_RootMyb_mean_MNm - DEL_base) / DEL_base;

    tablaMPC_OpenFAST.Delta_NAT_vs_Base_pct = ...
        100 * (tablaMPC_OpenFAST.NAT_pitch_total_pct - NAT_base) / NAT_base;

    tablaMPC_OpenFAST.Delta_PtfmPitch_vs_Base_pct = ...
        100 * (tablaMPC_OpenFAST.RMS_PtfmPitch_deg - PtfmPitch_base) / PtfmPitch_base;

    tablaMPC_OpenFAST.Delta_PtfmSurge_vs_Base_pct = ...
        100 * (tablaMPC_OpenFAST.RMS_PtfmSurge_m - PtfmSurge_base) / PtfmSurge_base;

end

disp("Tabla comparativa MPC open-loop en OpenFAST:"); %[output:879caa5b]
disp(tablaMPC_OpenFAST); %[output:8d95c493]

%% Guardar tabla

fileExcel = fullfile(outDir, 'comparativa_MPC_openloop_OpenFAST.xlsx');
fileCSV = fullfile(outDir, 'comparativa_MPC_openloop_OpenFAST.csv');

writetable(tablaMPC_OpenFAST, fileExcel, 'Sheet', 'Resumen');
writetable(tablaMPC_OpenFAST, fileCSV);

fprintf("\nTabla guardada en:\n%s\n", fileExcel); %[output:414bd3dd]

%% Gráficas de barras

plotBar(tablaMPC_OpenFAST, 'DEL_RootMyb_mean_MNm', ... %[output:group:817606a9] %[output:5c017653]
    'DEL medio RootMyb', 'DEL [MNm]', ... %[output:5c017653]
    fullfile(outDir, 'bar_DEL_MPC_OpenLoop.png')); %[output:group:817606a9] %[output:5c017653]

plotBar(tablaMPC_OpenFAST, 'NAT_pitch_total_pct', ... %[output:group:0fa3380f] %[output:49273f72]
    'Esfuerzo total de pitch', 'NAT pitch [%]', ... %[output:49273f72]
    fullfile(outDir, 'bar_NAT_total_MPC_OpenLoop.png')); %[output:group:0fa3380f] %[output:49273f72]

plotBar(tablaMPC_OpenFAST, 'RMS_IPC_mean_deg', ... %[output:group:64c59eaf] %[output:844cede9]
    'RMS pitch individual', 'RMS IPC [deg]', ... %[output:844cede9]
    fullfile(outDir, 'bar_RMS_IPC_MPC_OpenLoop.png')); %[output:group:64c59eaf] %[output:844cede9]

plotBar(tablaMPC_OpenFAST, 'RMS_PtfmPitch_deg', ... %[output:group:08694b6f] %[output:42c06883]
    'Movimiento plataforma pitch', 'RMS PtfmPitch [deg]', ... %[output:42c06883]
    fullfile(outDir, 'bar_PtfmPitch_MPC_OpenLoop.png')); %[output:group:08694b6f] %[output:42c06883]

plotBar(tablaMPC_OpenFAST, 'RMS_Mtilt_MNm', ... %[output:group:5a6f0086] %[output:2b70a2b6]
    'Carga MBC tilt', 'RMS Mtilt [MNm]', ... %[output:2b70a2b6]
    fullfile(outDir, 'bar_Mtilt_MPC_OpenLoop.png')); %[output:group:5a6f0086] %[output:2b70a2b6]

plotBar(tablaMPC_OpenFAST, 'RMS_Myaw_MNm', ... %[output:group:74edf5c0] %[output:8805295e]
    'Carga MBC yaw', 'RMS Myaw [MNm]', ... %[output:8805295e]
    fullfile(outDir, 'bar_Myaw_MPC_OpenLoop.png')); %[output:group:74edf5c0] %[output:8805295e]

%% Gráficas temporales comparativas

plotTemporal(signals, 'RootMyb1', 'RootMyb1', 'RootMyb1 [kN m]', ... %[output:group:44276e92] %[output:2054c228]
    [500 620], fullfile(outDir, 'temporal_RootMyb1_500_620.png')); %[output:group:44276e92] %[output:2054c228]

plotTemporal(signals, 'GenPwr_MW', 'Potencia generada', 'GenPwr [MW]', ... %[output:group:46fcf519] %[output:07b2ef55]
    [500 620], fullfile(outDir, 'temporal_GenPwr_500_620.png')); %[output:group:46fcf519] %[output:07b2ef55]

plotTemporal(signals, 'RotSpeed', 'Velocidad de rotor', 'RotSpeed [rpm]', ... %[output:group:8d76a7b3] %[output:23a4d22c]
    [500 620], fullfile(outDir, 'temporal_RotSpeed_500_620.png')); %[output:group:8d76a7b3] %[output:23a4d22c]

plotTemporal(signals, 'PtfmPitch', 'Pitch de plataforma', 'PtfmPitch [deg]', ... %[output:group:56818120] %[output:910865d9]
    [500 620], fullfile(outDir, 'temporal_PtfmPitch_500_620.png')); %[output:group:56818120] %[output:910865d9]

plotTemporal(signals, 'Mtilt', 'Carga MBC tilt', 'Mtilt [kN m]', ... %[output:group:8a9ba902] %[output:947a04eb]
    [500 620], fullfile(outDir, 'temporal_Mtilt_500_620.png')); %[output:group:8a9ba902] %[output:947a04eb]

plotTemporal(signals, 'Myaw', 'Carga MBC yaw', 'Myaw [kN m]', ... %[output:group:77846122] %[output:88847abd]
    [500 620], fullfile(outDir, 'temporal_Myaw_500_620.png')); %[output:group:77846122] %[output:88847abd]

%% Zoom pitch IPC del caso MPC open-loop

idxMPC = find(strcmp([signals.name], "OL_MPC"), 1);

if ~isempty(idxMPC) %[output:group:657cb257]

    t = signals(idxMPC).t;
    betaIPC = signals(idxMPC).betaIPC;

    idxZoom = t >= 500 & t <= 560;

    figure; %[output:84515ed7]
    hold on; grid on; %[output:84515ed7]
    plot(t(idxZoom), betaIPC(idxZoom,1), 'DisplayName','\beta_{IPC,1}'); %[output:84515ed7]
    plot(t(idxZoom), betaIPC(idxZoom,2), 'DisplayName','\beta_{IPC,2}'); %[output:84515ed7]
    plot(t(idxZoom), betaIPC(idxZoom,3), 'DisplayName','\beta_{IPC,3}'); %[output:84515ed7]
    xlabel('Tiempo [s]'); %[output:84515ed7]
    ylabel('Pitch individual [deg]'); %[output:84515ed7]
    title('Pitch IPC aplicado en OpenFAST - MPC open-loop'); %[output:84515ed7]
    legend('Location','best'); %[output:84515ed7]

    saveas(gcf, fullfile(outDir, 'zoom_betaIPC_MPC_OpenLoop_500_560.png')); %[output:84515ed7]
end %[output:group:657cb257]

%% Comprobación especial: Base original vs Open-loop base

idxOLBase = strcmp(tablaMPC_OpenFAST.Caso, 'Open-loop base');

if any(idxBase) && any(idxOLBase) %[output:group:9d554394]

    diffDEL_OLBase = tablaMPC_OpenFAST.Delta_DEL_vs_Base_pct(idxOLBase);
    diffNAT_OLBase = tablaMPC_OpenFAST.Delta_NAT_vs_Base_pct(idxOLBase);

    fprintf("\nComprobación Open-loop BASE vs Base original:\n"); %[output:7b6d44cf]
    fprintf("Diferencia DEL: %.3f %%n", diffDEL_OLBase); %[output:414b758e]
    fprintf("Diferencia NAT: %.3f %%n", diffNAT_OLBase); %[output:9ed9d196]

    if abs(diffDEL_OLBase) < 2
        fprintf("OK: el open-loop base reproduce razonablemente el DEL del caso base.\n"); %[output:9a203ec6]
    else
        fprintf("OJO: el open-loop base difiere bastante del caso base. Revisar antes de interpretar MPC.\n");
    end
end %[output:group:9d554394]

save(fullfile(outDir, 'comparativa_MPC_openloop_OpenFAST.mat'), ...
    'tablaMPC_OpenFAST', 'signals', '-v7.3');

fprintf("\nAnálisis terminado. Resultados en:\n%s\n", outDir); %[output:29dd8dd6]

%% ============================================================
% FUNCIONES AUXILIARES
% ============================================================

function outbFile = findOutb(folder)

    outbFile = "";

    if ~exist(folder, 'dir')
        warning("No existe la carpeta: %s", folder);
        return;
    end

    files = dir(fullfile(folder, '**', '*.outb'));

    if isempty(files)
        files = dir(fullfile(folder, '**', '*.out'));
    end

    if isempty(files)
        return;
    end

    % Preferir el archivo principal del modelo si existe
    names = string({files.name});
    idxMain = contains(names, "IEA-15-240-RWT-UMaineSemi", 'IgnoreCase', true);

    if any(idxMain)
        files = files(idxMain);
    end

    % Escoger el más reciente
    [~, idx] = max([files.datenum]);

    outbFile = string(fullfile(files(idx).folder, files(idx).name));
end

function names = cleanNames(raw)

    if ischar(raw)
        names = string(cellstr(raw));
    elseif isstring(raw)
        names = raw(:);
    elseif iscell(raw)
        names = strings(numel(raw),1);

        for i = 1:numel(raw)
            item = raw{i};

            if iscell(item)
                item = item{1};
            end

            names(i) = string(item);
        end
    else
        error("Formato de nombres no reconocido.");
    end

    names = strtrim(names(:));
end

function S = buildSignals(X, names, units)

    S.Time = getChan(X, names, "Time");

    S.GenPwr_MW = getChan(X, names, "GenPwr") / 1000;
    S.RotSpeed  = getChan(X, names, "RotSpeed");
    S.Azimuth   = getChan(X, names, "Azimuth");

    S.BldPitch1 = getPitchDeg(X, names, units, "BldPitch1");
    S.BldPitch2 = getPitchDeg(X, names, units, "BldPitch2");
    S.BldPitch3 = getPitchDeg(X, names, units, "BldPitch3");

    S.PtfmSurge = getChan(X, names, "PtfmSurge");
    S.PtfmPitch = getChan(X, names, "PtfmPitch");

    S.RootMyb1 = getChan(X, names, "RootMyb1");
    S.RootMyb2 = getChan(X, names, "RootMyb2");
    S.RootMyb3 = getChan(X, names, "RootMyb3");

    psi = deg2rad(S.Azimuth);

    S.Mtilt = (2/3) .* ( ...
        S.RootMyb1 .* cos(psi) + ...
        S.RootMyb2 .* cos(psi + 2*pi/3) + ...
        S.RootMyb3 .* cos(psi + 4*pi/3));

    S.Myaw = (2/3) .* ( ...
        S.RootMyb1 .* sin(psi) + ...
        S.RootMyb2 .* sin(psi + 2*pi/3) + ...
        S.RootMyb3 .* sin(psi + 4*pi/3));
end

function y = getChan(X, names, name)

    idx = find(strcmpi(names, name), 1);

    if isempty(idx)
        error("No encuentro el canal: %s", name);
    end

    y = X(:,idx);
end

function ydeg = getPitchDeg(X, names, units, name)

    idx = find(strcmpi(names, name), 1);

    if isempty(idx)
        error("No encuentro el canal: %s", name);
    end

    y = X(:,idx);

    unit = "";

    if numel(units) >= idx
        unit = lower(string(units(idx)));
    end

    if contains(unit, "rad")
        ydeg = rad2deg(y);
    else
        ydeg = y;
    end
end

function DEL = calcDEL(x, m, Neq)

    x = x(:);
    x = x - mean(x, 'omitnan');

    rf = rainflow(x);

    if istable(rf)
        ranges = rf.Range;
        counts = rf.Count;
    else
        % En MATLAB, cuando rainflow devuelve matriz:
        % columna 1 = Count
        % columna 2 = Range
        counts = rf(:,1);
        ranges = rf(:,2);
    end

    DEL = (sum(counts .* ranges.^m, 'omitnan') / Neq)^(1/m);
end

function NAT_pct = calcNAT(t, beta_deg, betaRateMax_deg_s)

    t = t(:);
    beta_deg = beta_deg(:);

    betaDot = zeros(size(beta_deg));
    betaDot(2:end) = diff(beta_deg) ./ diff(t);

    NAT_pct = 100 * mean(abs(betaDot), 'omitnan') / betaRateMax_deg_s;
end

function y = rmsDemean(x)

    x = x(:);
    x = x - mean(x, 'omitnan');
    y = rms(x, 'omitnan');
end

function plotBar(T, varName, figTitle, yLabelText, savePath)

    figure;
    bar(categorical(T.Caso), T.(varName));
    grid on;
    ylabel(yLabelText);
    title(figTitle);
    xtickangle(20);

    saveas(gcf, savePath);
end

function plotTemporal(signals, fieldName, figTitle, yLabelText, xlimVals, savePath)

    figure;
    hold on; grid on;

    for i = 1:numel(signals)

        if ~isfield(signals(i), 'S') || isempty(signals(i).S)
            continue;
        end

        S = signals(i).S;

        if ~isfield(S, fieldName)
            continue;
        end

        t = S.Time;
        y = S.(fieldName);

        idx = t >= xlimVals(1) & t <= xlimVals(2);

        plot(t(idx), y(idx), 'DisplayName', signals(i).label);
    end

    xlabel('Tiempo [s]');
    ylabel(yLabelText);
    title(figTitle);
    legend('Location','best');

    saveas(gcf, savePath);
end

